structure/notifications_profile_changes_operator_subject.txt <pre><code>    Owner details have been updated
</code></pre> structure/notifications_profile_changes_operator_message.txt <pre><code>    Owner of
    {% for o in organizations %}
        {{ o.name }} {% if o.abbreviation %} ({{ o.abbreviation }}){% endif %}{% if not forloop.last %}, {% endif %}
    {% endfor %}

    {{user.full_name}} (id={{ user.id }}) has changed

    {% for f in fields %}
        {{ f.name }} from {{ f.old_value }} to {{ f.new_value }}{% if not forloop.last %}, {% else %}.{% endif %}
    {% endfor %}
</code></pre> structure/notifications_profile_changes_operator_message.html <pre><code>    Owner of
    {% for o in organizations %}
        {{ o.name }} {% if o.abbreviation %} ({{ o.abbreviation }}){% endif %}{% if not forloop.last %}, {% endif %}
    {% endfor %}

    {{user.full_name}} (id={{ user.id }}) has changed

    {% for f in fields %}
        {{ f.name }} from {{ f.old_value }} to {{ f.new_value }}{% if not forloop.last %}, {% else %}.{% endif %}
    {% endfor %}
</code></pre>

structure/project_digest_subject.txt <pre><code>    {% load i18n %}{% blocktrans with org=organization_name %}Project Summary - {{ org }}{% endblocktrans %}
</code></pre> structure/project_digest_message.txt <pre><code>    {% load i18n %}{% trans "Project Summary" %} - {{ organization_name }}
    {% trans "Period" %}: {{ period_label }}

    {% for project in projects %}
    {{ project.name }}
    {% for section in project.sections %}
    {{ section.title }}
    {{ section.text_content }}
    {% endfor %}
    ---
    {% endfor %}

    {% blocktrans with org=organization_name %}This is an automated digest from {{ org }}.{% endblocktrans %}
</code></pre> structure/project_digest_message.html <pre><code>    {% load i18n %}
    &lt;!DOCTYPE html&gt;
    &lt;html&gt;
    &lt;body style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px;"&gt;
      &lt;h1 style="color: #333;"&gt;{% trans "Project Summary" %} - {{ organization_name }}&lt;/h1&gt;
      &lt;p style="color: #666;"&gt;{% trans "Period" %}: {{ period_label }}&lt;/p&gt;

      {% for project in projects %}
        &lt;h2 style="color: #444; border-bottom: 1px solid #ddd; padding-bottom: 8px;"&gt;{{ project.name }}&lt;/h2&gt;
        {% for section in project.sections %}
          &lt;h3 style="color: #555;"&gt;{{ section.title }}&lt;/h3&gt;
          {{ section.html_content|safe }}
        {% endfor %}
        &lt;hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;"&gt;
      {% endfor %}

      &lt;p style="color: #999; font-size: 12px;"&gt;
        {% blocktrans with org=organization_name %}This is an automated digest from {{ org }}.{% endblocktrans %}
      &lt;/p&gt;
    &lt;/body&gt;
    &lt;/html&gt;
</code></pre>

users/invitation_approved_subject.txt <pre><code>    Account has been created
</code></pre> users/invitation_approved_message.txt <pre><code>    Hello!

    {{ sender }} has invited you to join {{ name }} {{ type }} in {{ role }} role.
    Please visit the link below to sign up and accept your invitation:
    {{ link }}

